create table g_hk_counterparty(id string comment '主键',client_id string comment '交易对手编号',client_type string comment '客户类型',client_name string comment '客户名称',full_name string comment '全称',abbreviation string comment '简称',name_abbreviation string comment '缩写',unifiedsocial_code string comment '公司注册码',involve_cross_sale string comment '是否涉及交叉销售收入',allow_busi_type string comment '拟参与业务类型',allow_busi_type_other string comment '拟参与业务类型-其它',underlying_type string comment '业务挂钩标的类型',funds_interest_repayment string comment '客户资金是否需要返息',funds_cross_sale_ratio string comment '资金交叉收入比例',deriv_cross_sale_ratio string comment '衍生品交叉收入比例',trade_way string comment '交易方式',trade_way_other string comment '交易方式-其它',open_account_complete string comment '开户是否完成',isda_complete string comment 'ISDA是否完成',open_account_complete_date string comment '开户完成日期',isda_signed_date string comment 'ISDA签署日期',isda_signed_doc_archive string comment 'ISDA双方签署资料是否归档',open_account_doc_archive string comment '开户资料是否归档',create_date string comment '创建时间',create_by string comment '创建人',update_date string comment '更新时间',update_by string comment '更新人',delete_flag string comment '逻辑删除标识，0未删除1删除',audit_status string comment '审核状态',data_time string comment '数据时间') partitioned by (busi_date string comment '数据日期') row format delimited fields terminated by ',' stored as textfile;
